async function paged(make) {
	const out = [];
	for (let from = 0; from < MAX_ROWS; from += PAGE) {
		const { data, error } = await make(from, from + PAGE - 1);
		if (error) throw new Error(error.message);
		out.push(...data ?? []);
		if (!data || data.length < PAGE) break;
	}
	return out;
}
